import collections
def components(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen or g[y][x]!=col: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==col:
                                st.append((ny,nx))
                out.append((col,len(comp),comp))
    return sorted(out,key=lambda t:t[0])
